# You need to have Administrator rights to run this script!
    if (-not([Security.Principal.WindowsPrincipal] [Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole([Security.Principal.WindowsBuiltInRole] "Administrator")) {
        Write-Warning "You need to have Administrator rights to run this script!`nPlease re-run this script as an Administrator in an elevated powershell prompt!"
        Start-Process -Verb runas -FilePath powershell.exe -ArgumentList "-ExecutionPolicy Bypass -File `"$PSCommandPath`""
        break
    }

# Load ddls to the current session.
    [Console]::OutputEncoding = [System.Text.Encoding]::UTF8
    $OutputEncoding = [System.Text.Encoding]::UTF8
    Add-Type -AssemblyName PresentationFramework, System.Drawing, PresentationCore, WindowsFormsIntegration, System.Windows.Forms
    [System.Windows.Forms.Application]::EnableVisualStyles()

    # Pre-cache micro flag icons for UI
    $flagCache = (Join-Path $env:TEMP "OfficeInstallerFlags").Replace("\", "/")
    if (-not (Test-Path $flagCache)) { New-Item -ItemType Directory -Path $flagCache | Out-Null }
    
    # SoftVN & Microsoft Official Brand Assets (Base64 embedded for 100% offline standalone execution)
    $softvnIconBase64 = ""
    $softvnLogoBase64 = ""
    $msIconBase64 = ""
    
    $softvnIconFile = "$flagCache/softvn_icon.png"
    if (-not (Test-Path $softvnIconFile)) {
        try { [System.IO.File]::WriteAllBytes($softvnIconFile, [System.Convert]::FromBase64String($softvnIconBase64)) } catch {}
    }
    $softvnLogoFile = "$flagCache/softvn_logo.png"
    if (-not (Test-Path $softvnLogoFile)) {
        try { [System.IO.File]::WriteAllBytes($softvnLogoFile, [System.Convert]::FromBase64String($softvnLogoBase64)) } catch {}
    }
    $msIconFile = "$flagCache/ms_icon.png"
    if (-not (Test-Path $msIconFile)) {
        try { [System.IO.File]::WriteAllBytes($msIconFile, [System.Convert]::FromBase64String($msIconBase64)) } catch {}
    }

    # Microsoft Fluent Brand Icons (Base64 embedded for 100% offline standalone execution)
$fluentIcons = @{
    'word' = ''
    'excel' = ''
    'powerpoint' = ''
    'outlook' = ''
    'onenote' = ''
    'access' = ''
    'publisher' = ''
    'visio' = ''
    'project' = ''
    'office' = ''
    'm365' = ''
}
foreach ($k in $fluentIcons.Keys) {
    $dest = "$flagCache/$k.png"
    if (-not (Test-Path $dest)) {
        try { [System.IO.File]::WriteAllBytes($dest, [System.Convert]::FromBase64String($fluentIcons[$k])) } catch {}
    }
}

    
    $flagSources = @{
        "us" = "https://flagcdn.com/w40/us.png"
        "vn" = "https://flagcdn.com/w40/vn.png"
        "jp" = "https://flagcdn.com/w40/jp.png"
        "kr" = "https://flagcdn.com/w40/kr.png"
        "cn" = "https://flagcdn.com/w40/cn.png"
        "fr" = "https://flagcdn.com/w40/fr.png"
        "es" = "https://flagcdn.com/w40/es.png"
        "de" = "https://flagcdn.com/w40/de.png"
        "it" = "https://flagcdn.com/w40/it.png"
        "br" = "https://flagcdn.com/w40/br.png"
        "ru" = "https://flagcdn.com/w40/ru.png"
        "sa" = "https://flagcdn.com/w40/sa.png"
        "office" = "https://raw.githubusercontent.com/walkxcode/dashboard-icons/main/png/microsoft-office.png"
    }
    
    [Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12 -bor [Net.SecurityProtocolType]::Tls13
    $wcFlags = New-Object System.Net.WebClient
    $wcFlags.Headers.Add("User-Agent", "Mozilla/5.0")
    foreach ($k in $flagSources.Keys) {
        $dest = "$flagCache/$k.png"
        if (-not (Test-Path $dest)) {
            try { $wcFlags.DownloadFile($flagSources[$k], $dest) } catch {}
        }
    }

$xamlInput = @'
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
        xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        Title="Microsoft Office Deployment Utility - Ph&#x1EA7;n m&#x1EC1;m b&#x1EA3;n quy&#x1EC1;n - https://softvn.vn" 
        Icon="__FLAG_DIR__/ms_icon.png"
        Width="1280" Height="790" Background="{DynamicResource BrushWindowBg}"
        WindowStartupLocation="CenterScreen"
        FontFamily="Segoe UI Variable, Segoe UI, sans-serif">
    
    <Window.Resources>
        <!-- Fluent Theme System Brushes (Light Mode Defaults) -->
        <SolidColorBrush x:Key="BrushWindowBg" Color="#FFF1F5F9"/>
        <SolidColorBrush x:Key="BrushRailBg" Color="#FFFFFFFF"/>
        <SolidColorBrush x:Key="BrushRailBorder" Color="#FFE2E8F0"/>
        <SolidColorBrush x:Key="BrushRailBtnHover" Color="#FFF8FAFC"/>
        <SolidColorBrush x:Key="BrushRailBtnSelected" Color="#EEF2FF"/>
        <SolidColorBrush x:Key="BrushNavBtnHoverText" Color="#FF0F172A"/>
        <SolidColorBrush x:Key="BrushNavBtnActiveText" Color="#FF4F46E5"/>
        <SolidColorBrush x:Key="BrushCardBg" Color="#FFFFFFFF"/>
        <SolidColorBrush x:Key="BrushCardBorder" Color="#FFE2E8F0"/>
        <SolidColorBrush x:Key="BrushSubCardBg" Color="#FFFFFFFF"/>
        <SolidColorBrush x:Key="BrushSubCardBorder" Color="#FFE2E8F0"/>
        <SolidColorBrush x:Key="BrushTileBg" Color="#FFF8FAFC"/>
        <SolidColorBrush x:Key="BrushTileBorder" Color="#FFE2E8F0"/>
        <SolidColorBrush x:Key="BrushTileHoverBg" Color="#FFF1F5F9"/>
        <SolidColorBrush x:Key="BrushTileHoverBorder" Color="#FFCBD5E1"/>
        <SolidColorBrush x:Key="BrushTileActiveBg" Color="#EEF2FF"/>
        <SolidColorBrush x:Key="BrushTileActiveBorder" Color="#FF6366F1"/>
        <SolidColorBrush x:Key="BrushTileActiveText" Color="#FF4F46E5"/>
        <SolidColorBrush x:Key="BrushCapsuleBg" Color="#FFFFFFFF"/>
        <SolidColorBrush x:Key="BrushCapsuleBorder" Color="#FFE2E8F0"/>
        <SolidColorBrush x:Key="BrushPillHoverBg" Color="#FFF1F5F9"/>
        <SolidColorBrush x:Key="BrushPillActiveBg" Color="#EEF2FF"/>
        <SolidColorBrush x:Key="BrushPillActiveText" Color="#FF4F46E5"/>
        <SolidColorBrush x:Key="BrushComboHoverBg" Color="#FFF1F5F9"/>
        <SolidColorBrush x:Key="BrushComboItemHover" Color="#FFF1F5F9"/>
        <SolidColorBrush x:Key="BrushComboItemSelected" Color="#EEF2FF"/>
        <SolidColorBrush x:Key="BrushTextPrimary" Color="#FF0F172A"/>
        <SolidColorBrush x:Key="BrushTextSecondary" Color="#FF64748B"/>
        <SolidColorBrush x:Key="BrushTextMuted" Color="#FF94A3B8"/>
        <SolidColorBrush x:Key="BrushSecBtnBg" Color="#FFFFFFFF"/>
        <SolidColorBrush x:Key="BrushSecBtnBorder" Color="#FFE2E8F0"/>
        <SolidColorBrush x:Key="BrushSecBtnHover" Color="#FFF8FAFC"/>
        <SolidColorBrush x:Key="BrushSecBtnText" Color="#FF1E293B"/>
        <SolidColorBrush x:Key="BrushFlagBtnBg" Color="#FFFFFFFF"/>
        <SolidColorBrush x:Key="BrushFlagBtnBorder" Color="#FFE2E8F0"/>
        <SolidColorBrush x:Key="BrushFlagBtnHoverBg" Color="#FFF8FAFC"/>
        <SolidColorBrush x:Key="BrushConsoleBg" Color="#FF0B0F19"/>
        <SolidColorBrush x:Key="BrushConsoleBorder" Color="#FF1E293B"/>
        <SolidColorBrush x:Key="BrushConsoleHeader" Color="#FF111827"/>
        <SolidColorBrush x:Key="BrushConsoleHeaderText" Color="#FF94A3B8"/>
        <SolidColorBrush x:Key="BrushConsoleText" Color="#FF38BDF8"/>
        <SolidColorBrush x:Key="BrushScrollThumb" Color="#FFE2E8F0"/>
        <SolidColorBrush x:Key="BrushConsoleScrollThumb" Color="#FF334155"/>
        <SolidColorBrush x:Key="BrushAccent365" Color="#FF4F46E5"/>
        <SolidColorBrush x:Key="BrushAccent2024" Color="#D97706"/>
        <SolidColorBrush x:Key="BrushAccent2021" Color="#059669"/>
        <SolidColorBrush x:Key="BrushAccent2019" Color="#0284C7"/>
        <SolidColorBrush x:Key="BrushAccentLegacy" Color="#7C3AED"/>
        <SolidColorBrush x:Key="BrushAccentProject" Color="#0284C7"/>
        <SolidColorBrush x:Key="BrushAccentVisio" Color="#4F46E5"/>
        <SolidColorBrush x:Key="BrushAccentMac" Color="#FF0F172A"/>
        <SolidColorBrush x:Key="BrushAccentTools" Color="#E11D48"/>

        <!-- Fluent Left Rail Navigation Item Style -->
        <Style TargetType="RadioButton" x:Key="FluentNavRailBtn">
            <Setter Property="Background" Value="Transparent"/>
            <Setter Property="Foreground" Value="{DynamicResource BrushTextSecondary}"/>
            <Setter Property="Height" Value="52"/>
            <Setter Property="Width" Value="56"/>
            <Setter Property="Margin" Value="0,3"/>
            <Setter Property="Cursor" Value="Hand"/>
            <Setter Property="Template">
                <Setter.Value>
                    <ControlTemplate TargetType="RadioButton">
                        <Grid Background="{TemplateBinding Background}">
                            <!-- Active Indicator Pill on the left edge -->
                            <Rectangle Name="Indicator" HorizontalAlignment="Left" Width="3.5" Height="22" RadiusX="1.7" RadiusY="1.7" Fill="#FF6366F1" Visibility="Collapsed"/>
                            <Border Name="HoverBorder" Background="Transparent" CornerRadius="8" Margin="6,4">
                                <ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center"/>
                            </Border>
                        </Grid>
                        <ControlTemplate.Triggers>
                            <Trigger Property="IsChecked" Value="True">
                                <Setter TargetName="Indicator" Property="Visibility" Value="Visible"/>
                                <Setter TargetName="HoverBorder" Property="Background" Value="{DynamicResource BrushRailBtnSelected}"/>
                                <Setter Property="Foreground" Value="{DynamicResource BrushNavBtnActiveText}"/>
                            </Trigger>
                            <Trigger Property="IsMouseOver" Value="True">
                                <Setter TargetName="HoverBorder" Property="Background" Value="{DynamicResource BrushRailBtnHover}"/>
                                <Setter Property="Foreground" Value="{DynamicResource BrushNavBtnHoverText}"/>
                            </Trigger>
                        </ControlTemplate.Triggers>
                    </ControlTemplate>
                </Setter.Value>
            </Setter>
        </Style>

        <!-- Fluent Card Style -->
        <Style TargetType="Border" x:Key="FluentCard">
            <Setter Property="Background" Value="{DynamicResource BrushCardBg}"/>
            <Setter Property="BorderBrush" Value="{DynamicResource BrushCardBorder}"/>
            <Setter Property="BorderThickness" Value="1"/>
            <Setter Property="CornerRadius" Value="10"/>
            <Setter Property="Padding" Value="10,10"/>
        </Style>

        <!-- Fluent Segmented Pill Radio (Outline style) -->
        <Style TargetType="RadioButton" x:Key="SegmentedRadio">
            <Setter Property="Foreground" Value="{DynamicResource BrushTextSecondary}"/>
            <Setter Property="FontSize" Value="11"/>
            <Setter Property="FontWeight" Value="SemiBold"/>
            <Setter Property="Cursor" Value="Hand"/>
            <Setter Property="Template">
                <Setter.Value>
                    <ControlTemplate TargetType="RadioButton">
                        <Border Name="PillBorder" Background="Transparent" BorderBrush="Transparent" BorderThickness="1" CornerRadius="5" Padding="8,3.5">
                            <ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center"/>
                        </Border>
                        <ControlTemplate.Triggers>
                            <Trigger Property="IsChecked" Value="True">
                                <Setter TargetName="PillBorder" Property="Background" Value="{DynamicResource BrushPillActiveBg}"/>
                                <Setter TargetName="PillBorder" Property="BorderBrush" Value="#FF6366F1"/>
                                <Setter Property="Foreground" Value="{DynamicResource BrushPillActiveText}"/>
                                <Setter Property="FontWeight" Value="Bold"/>
                            </Trigger>
                            <Trigger Property="IsMouseOver" Value="True">
                                <Setter TargetName="PillBorder" Property="Background" Value="{DynamicResource BrushPillHoverBg}"/>
                            </Trigger>
                        </ControlTemplate.Triggers>
                    </ControlTemplate>
                </Setter.Value>
            </Setter>
        </Style>

        <!-- Fluent ComboBox Style -->
        <ControlTemplate x:Key="FluentComboBoxToggleButton" TargetType="{x:Type ToggleButton}">
            <Border x:Name="templateRoot" Background="{DynamicResource BrushCapsuleBg}" BorderBrush="{DynamicResource BrushCapsuleBorder}" BorderThickness="1" CornerRadius="6">
                <Border x:Name="splitBorder" Width="22" HorizontalAlignment="Right" Margin="0">
                    <Path x:Name="arrow" Data="M 0 0 L 3.5 3.5 L 7 0 Z" Fill="{DynamicResource BrushTextSecondary}" HorizontalAlignment="Center" VerticalAlignment="Center"/>
                </Border>
            </Border>
            <ControlTemplate.Triggers>
                <Trigger Property="IsMouseOver" Value="true">
                    <Setter TargetName="templateRoot" Property="BorderBrush" Value="#FF6366F1"/>
                    <Setter TargetName="templateRoot" Property="Background" Value="{DynamicResource BrushComboHoverBg}"/>
                    <Setter TargetName="arrow" Property="Fill" Value="{DynamicResource BrushTextPrimary}"/>
                </Trigger>
            </ControlTemplate.Triggers>
        </ControlTemplate>

        <Style TargetType="{x:Type ComboBox}" x:Key="FluentComboBox">
            <Setter Property="Foreground" Value="{DynamicResource BrushTextPrimary}"/>
            <Setter Property="Background" Value="{DynamicResource BrushCapsuleBg}"/>
            <Setter Property="BorderBrush" Value="{DynamicResource BrushCapsuleBorder}"/>
            <Setter Property="BorderThickness" Value="1"/>
            <Setter Property="Height" Value="28"/>
            <Setter Property="Padding" Value="8,2"/>
            <Setter Property="FontSize" Value="11"/>
            <Setter Property="FontWeight" Value="SemiBold"/>
            <Setter Property="Cursor" Value="Hand"/>
            <Setter Property="Template">
                <Setter.Value>
                    <ControlTemplate TargetType="{x:Type ComboBox}">
                        <Grid x:Name="templateRoot">
                            <ToggleButton x:Name="toggleButton" Template="{StaticResource FluentComboBoxToggleButton}" Focusable="false" IsChecked="{Binding Path=IsDropDownOpen, Mode=TwoWay, RelativeSource={RelativeSource TemplatedParent}}"/>
                            <ContentPresenter x:Name="contentPresenter" Content="{Binding Path=SelectedItem.Content, RelativeSource={RelativeSource TemplatedParent}}" HorizontalAlignment="Left" Margin="8,0,24,0" VerticalAlignment="Center" IsHitTestVisible="False"/>
                            <Popup x:Name="PART_Popup" AllowsTransparency="true" IsOpen="{Binding Path=IsDropDownOpen, RelativeSource={RelativeSource TemplatedParent}}" Placement="Bottom" Margin="1">
                                <Border x:Name="dropDownBorder" Background="{DynamicResource BrushCardBg}" BorderBrush="{DynamicResource BrushCardBorder}" BorderThickness="1" CornerRadius="6" MaxHeight="250" MinWidth="{Binding ActualWidth, ElementName=templateRoot}">
                                    <ScrollViewer x:Name="DropDownScrollViewer">
                                        <ItemsPresenter x:Name="ItemsPresenter" KeyboardNavigation.DirectionalNavigation="Contained"/>
                                    </ScrollViewer>
                                </Border>
                            </Popup>
                        </Grid>
                    </ControlTemplate>
                </Setter.Value>
            </Setter>
        </Style>

        <Style TargetType="ComboBoxItem" x:Key="FluentComboBoxItem">
            <Setter Property="Background" Value="{DynamicResource BrushCardBg}"/>
            <Setter Property="Foreground" Value="{DynamicResource BrushTextPrimary}"/>
            <Setter Property="FontSize" Value="11.5"/>
            <Setter Property="Padding" Value="8,5"/>
            <Setter Property="Cursor" Value="Hand"/>
            <Setter Property="Template">
                <Setter.Value>
                    <ControlTemplate TargetType="ComboBoxItem">
                        <Border x:Name="ItemBorder" Background="{TemplateBinding Background}" Padding="{TemplateBinding Padding}" CornerRadius="4" Margin="2,1">
                            <ContentPresenter HorizontalAlignment="Left" VerticalAlignment="Center"/>
                        </Border>
                        <ControlTemplate.Triggers>
                            <Trigger Property="IsMouseOver" Value="True">
                                <Setter TargetName="ItemBorder" Property="Background" Value="{DynamicResource BrushComboItemHover}"/>
                                <Setter Property="Foreground" Value="{DynamicResource BrushTextPrimary}"/>
                            </Trigger>
                            <Trigger Property="IsSelected" Value="True">
                                <Setter TargetName="ItemBorder" Property="Background" Value="{DynamicResource BrushComboItemSelected}"/>
                                <Setter Property="Foreground" Value="{DynamicResource BrushTextPrimary}"/>
                            </Trigger>
                        </ControlTemplate.Triggers>
                    </ControlTemplate>
                </Setter.Value>
            </Setter>
        </Style>

        <!-- Fluent Language Item Style -->
        <Style TargetType="RadioButton" x:Key="LanguageTileRadio">
            <Setter Property="Foreground" Value="{DynamicResource BrushTextPrimary}"/>
            <Setter Property="FontSize" Value="11.5"/>
            <Setter Property="Cursor" Value="Hand"/>
            <Setter Property="Margin" Value="0,1.5"/>
            <Setter Property="Template">
                <Setter.Value>
                    <ControlTemplate TargetType="RadioButton">
                        <Border Name="TileBorder" Background="{DynamicResource BrushTileBg}" BorderBrush="{DynamicResource BrushTileBorder}" BorderThickness="1" CornerRadius="6" Padding="8,4.5">
                            <Grid>
                                <Grid.ColumnDefinitions>
                                    <ColumnDefinition Width="Auto"/>
                                    <ColumnDefinition Width="*"/>
                                    <ColumnDefinition Width="Auto"/>
                                </Grid.ColumnDefinitions>
                                <ContentPresenter Grid.Column="1" VerticalAlignment="Center" Margin="2,0,0,0"/>
                                <Ellipse Name="Dot" Grid.Column="2" Width="5" Height="5" Fill="#FF6366F1" Visibility="Collapsed" VerticalAlignment="Center"/>
                            </Grid>
                        </Border>
                        <ControlTemplate.Triggers>
                            <Trigger Property="IsChecked" Value="True">
                                <Setter TargetName="TileBorder" Property="Background" Value="{DynamicResource BrushTileActiveBg}"/>
                                <Setter TargetName="TileBorder" Property="BorderBrush" Value="#FF6366F1"/>
                                <Setter TargetName="Dot" Property="Visibility" Value="Visible"/>
                                <Setter Property="Foreground" Value="{DynamicResource BrushTileActiveText}"/>
                                <Setter Property="FontWeight" Value="SemiBold"/>
                            </Trigger>
                            <Trigger Property="IsMouseOver" Value="True">
                                <Setter TargetName="TileBorder" Property="BorderBrush" Value="{DynamicResource BrushTileHoverBorder}"/>
                                <Setter TargetName="TileBorder" Property="Background" Value="{DynamicResource BrushTileHoverBg}"/>
                            </Trigger>
                        </ControlTemplate.Triggers>
                    </ControlTemplate>
                </Setter.Value>
            </Setter>
        </Style>

        <!-- Fluent Product Selection Tile -->
        <Style TargetType="RadioButton" x:Key="CardTileRadio">
            <Setter Property="Foreground" Value="{DynamicResource BrushTextPrimary}"/>
            <Setter Property="FontSize" Value="11.5"/>
            <Setter Property="Cursor" Value="Hand"/>
            <Setter Property="Margin" Value="0,1.5"/>
            <Setter Property="Template">
                <Setter.Value>
                    <ControlTemplate TargetType="RadioButton">
                        <Border Name="TileBorder" Background="{DynamicResource BrushTileBg}" BorderBrush="{DynamicResource BrushTileBorder}" BorderThickness="1" CornerRadius="5" Padding="6,2.5">
                            <Grid>
                                <Grid.ColumnDefinitions>
                                    <ColumnDefinition Width="*"/>
                                    <ColumnDefinition Width="Auto"/>
                                </Grid.ColumnDefinitions>
                                <ContentPresenter Grid.Column="0" VerticalAlignment="Center"/>
                                <Ellipse Name="Dot" Grid.Column="1" Width="5" Height="5" Fill="#FF6366F1" Visibility="Collapsed" VerticalAlignment="Center"/>
                            </Grid>
                        </Border>
                        <ControlTemplate.Triggers>
                            <Trigger Property="IsChecked" Value="True">
                                <Setter TargetName="TileBorder" Property="Background" Value="{DynamicResource BrushTileActiveBg}"/>
                                <Setter TargetName="TileBorder" Property="BorderBrush" Value="#FF6366F1"/>
                                <Setter TargetName="Dot" Property="Visibility" Value="Visible"/>
                                <Setter Property="Foreground" Value="{DynamicResource BrushTileActiveText}"/>
                                <Setter Property="FontWeight" Value="SemiBold"/>
                            </Trigger>
                            <Trigger Property="IsMouseOver" Value="True">
                                <Setter TargetName="TileBorder" Property="BorderBrush" Value="{DynamicResource BrushTileHoverBorder}"/>
                                <Setter TargetName="TileBorder" Property="Background" Value="{DynamicResource BrushTileHoverBg}"/>
                            </Trigger>
                        </ControlTemplate.Triggers>
                    </ControlTemplate>
                </Setter.Value>
            </Setter>
        </Style>

        <!-- Secondary Action Button Style -->
        <Style TargetType="Button" x:Key="SecondaryButton">
            <Setter Property="Background" Value="{DynamicResource BrushSecBtnBg}"/>
            <Setter Property="Foreground" Value="{DynamicResource BrushSecBtnText}"/>
            <Setter Property="BorderBrush" Value="{DynamicResource BrushSecBtnBorder}"/>
            <Setter Property="BorderThickness" Value="1"/>
            <Setter Property="FontSize" Value="11"/>
            <Setter Property="FontWeight" Value="SemiBold"/>
            <Setter Property="Cursor" Value="Hand"/>
            <Setter Property="Template">
                <Setter.Value>
                    <ControlTemplate TargetType="Button">
                        <Border Name="SecBtnBorder" Background="{TemplateBinding Background}" BorderBrush="{TemplateBinding BorderBrush}" BorderThickness="{TemplateBinding BorderThickness}" CornerRadius="6" Padding="10,6">
                            <ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center"/>
                        </Border>
                        <ControlTemplate.Triggers>
                            <Trigger Property="IsMouseOver" Value="True">
                                <Setter TargetName="SecBtnBorder" Property="Background" Value="{DynamicResource BrushSecBtnHover}"/>
                                <Setter TargetName="SecBtnBorder" Property="BorderBrush" Value="#FF6366F1"/>
                            </Trigger>
                        </ControlTemplate.Triggers>
                    </ControlTemplate>
                </Setter.Value>
            </Setter>
        </Style>

        <!-- Interactive Flag Download Button Style -->
        <Style TargetType="Button" x:Key="FlagDownloadBtn">
            <Setter Property="Background" Value="{DynamicResource BrushFlagBtnBg}"/>
            <Setter Property="BorderBrush" Value="{DynamicResource BrushFlagBtnBorder}"/>
            <Setter Property="BorderThickness" Value="1"/>
            <Setter Property="Height" Value="24"/>
            <Setter Property="Padding" Value="6,2"/>
            <Setter Property="Margin" Value="2,0"/>
            <Setter Property="Cursor" Value="Hand"/>
            <Setter Property="Template">
                <Setter.Value>
                    <ControlTemplate TargetType="Button">
                        <Border Name="FDBorder" Background="{TemplateBinding Background}" BorderBrush="{TemplateBinding BorderBrush}" BorderThickness="{TemplateBinding BorderThickness}" CornerRadius="5" Padding="{TemplateBinding Padding}">
                            <ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center"/>
                        </Border>
                        <ControlTemplate.Triggers>
                            <Trigger Property="IsMouseOver" Value="True">
                                <Setter TargetName="FDBorder" Property="Background" Value="{DynamicResource BrushFlagBtnHoverBg}"/>
                                <Setter TargetName="FDBorder" Property="BorderBrush" Value="#FF6366F1"/>
                            </Trigger>
                        </ControlTemplate.Triggers>
                    </ControlTemplate>
                </Setter.Value>
            </Setter>
        </Style>

        <!-- Icon-only Download Button Style -->
        <Style TargetType="Button" x:Key="MiniDownloadBtn">
            <Setter Property="Background" Value="{DynamicResource BrushFlagBtnBg}"/>
            <Setter Property="Foreground" Value="{DynamicResource BrushTextPrimary}"/>
            <Setter Property="BorderBrush" Value="{DynamicResource BrushFlagBtnBorder}"/>
            <Setter Property="BorderThickness" Value="1"/>
            <Setter Property="Width" Value="26"/>
            <Setter Property="Height" Value="24"/>
            <Setter Property="Cursor" Value="Hand"/>
            <Setter Property="ToolTip" Value="Download Installer"/>
            <Setter Property="Template">
                <Setter.Value>
                    <ControlTemplate TargetType="Button">
                        <Border Name="MDBorder" Background="{TemplateBinding Background}" BorderBrush="{TemplateBinding BorderBrush}" BorderThickness="{TemplateBinding BorderThickness}" CornerRadius="5">
                            <ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center"/>
                        </Border>
                        <ControlTemplate.Triggers>
                            <Trigger Property="IsMouseOver" Value="True">
                                <Setter TargetName="MDBorder" Property="Background" Value="{DynamicResource BrushFlagBtnHoverBg}"/>
                                <Setter TargetName="MDBorder" Property="BorderBrush" Value="#FF6366F1"/>
                            </Trigger>
                        </ControlTemplate.Triggers>
                    </ControlTemplate>
                </Setter.Value>
            </Setter>
        </Style>

        <!-- Danger Action Button Style -->
        <Style TargetType="Button" x:Key="DangerButton">
            <Setter Property="Background" Value="#FFE11D48"/>
            <Setter Property="Foreground" Value="#FFFFFFFF"/>
            <Setter Property="BorderThickness" Value="0"/>
            <Setter Property="FontSize" Value="12"/>
            <Setter Property="FontWeight" Value="Bold"/>
            <Setter Property="Cursor" Value="Hand"/>
            <Setter Property="Template">
                <Setter.Value>
                    <ControlTemplate TargetType="Button">
                        <Border Name="DngBtnBorder" Background="{TemplateBinding Background}" CornerRadius="6" Padding="14,8">
                            <ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center"/>
                        </Border>
                        <ControlTemplate.Triggers>
                            <Trigger Property="IsMouseOver" Value="True">
                                <Setter TargetName="DngBtnBorder" Property="Background" Value="#FFBE123C"/>
                            </Trigger>
                        </ControlTemplate.Triggers>
                    </ControlTemplate>
                </Setter.Value>
            </Setter>
        </Style>

        <!-- Sleek Fluent Scrollbar Style (4px Modern Slim) -->
        <Style TargetType="{x:Type ScrollBar}">
            <Setter Property="Background" Value="Transparent"/>
            <Setter Property="Width" Value="4"/>
            <Setter Property="Template">
                <Setter.Value>
                    <ControlTemplate TargetType="{x:Type ScrollBar}">
                        <Grid Background="Transparent">
                            <Track x:Name="PART_Track" IsDirectionReversed="true">
                                <Track.Thumb>
                                    <Thumb>
                                        <Thumb.Template>
                                            <ControlTemplate TargetType="{x:Type Thumb}">
                                                <Border Background="{DynamicResource BrushScrollThumb}" CornerRadius="2"/>
                                            </ControlTemplate>
                                        </Thumb.Template>
                                    </Thumb>
                                </Track.Thumb>
                            </Track>
                        </Grid>
                    </ControlTemplate>
                </Setter.Value>
            </Setter>
        </Style>

        <Style TargetType="RadioButton" x:Key="SidebarRadio">
            <Setter Property="Margin" Value="0,3,0,3"/>
            <Setter Property="Foreground" Value="{DynamicResource BrushTextSecondary}"/>
            <Setter Property="FontSize" Value="11"/>
            <Setter Property="Cursor" Value="Hand"/>
        </Style>
    </Window.Resources>

    <Grid Background="{DynamicResource BrushWindowBg}">
        <Grid.ColumnDefinitions>
            <!-- Column 0: Left Nav Rail (Office Tool Plus Style) -->
            <ColumnDefinition Width="64"/>
            <!-- Column 1: Main Work Area -->
            <ColumnDefinition Width="*"/>
        </Grid.ColumnDefinitions>

        <!-- COLUMN 0: FLUENT NAVIGATION RAIL -->
        <Border Grid.Column="0" Background="{DynamicResource BrushRailBg}" BorderBrush="{DynamicResource BrushRailBorder}" BorderThickness="0,0,1,0">
            <Grid>
                <Grid.RowDefinitions>
                    <RowDefinition Height="Auto"/> <!-- Brand App Logo -->
                    <RowDefinition Height="*"/>    <!-- Nav Buttons -->
                    <RowDefinition Height="Auto"/> <!-- Bottom Help / Version -->
                </Grid.RowDefinitions>

