        Light = @{
            BrushWindowBg           = "#FFF1F5F9"
            BrushRailBg             = "#FFFFFFFF"
            BrushRailBorder         = "#FFE2E8F0"
            BrushRailBtnHover       = "#FFF8FAFC"
