            BrushSecBtnText         = "#FF1E293B"
            BrushFlagBtnBg          = "#FFFFFFFF"
            BrushFlagBtnBorder      = "#FFE2E8F0"
            BrushFlagBtnHoverBg     = "#FFF8FAFC"
            BrushConsoleBg          = "#FF0B0F19"
            BrushConsoleBorder      = "#FF1E293B"
            BrushConsoleHeader      = "#FF111827"
