    function Apply-AppTheme {
        param([bool]$IsDark)
        $themeName = if ($IsDark) { "Dark" } else { "Light" }
        $palette = $themeColors[$themeName]

        foreach ($key in $palette.Keys) {
            $colorHex = $palette[$key]
            $brush = [Windows.Media.SolidColorBrush][Windows.Media.ColorConverter]::ConvertFromString($colorHex)
            $brush.Freeze()
            $Form.Resources[$key] = $brush
        }

        if ($iconThemeToggle) {
            if ($IsDark) {
                # Dark Mode active -> Show Sun icon to switch to Light Mode
                $iconThemeToggle.Data = [Windows.Media.Geometry]::Parse($pathSun)
                $buttonThemeToggle.ToolTip = "Switch to Light Mode"
            } else {
                # Light Mode active -> Show Moon icon to switch to Dark Mode
                $iconThemeToggle.Data = [Windows.Media.Geometry]::Parse($pathMoon)
                $buttonThemeToggle.ToolTip = "Switch to Dark Mode"
            }
        }
    }

    if ($buttonThemeToggle) {
        $buttonThemeToggle.Add_Click({
            $global:isDarkMode = -not $global:isDarkMode
            Apply-AppTheme -IsDark $global:isDarkMode
            $currentMode = if ($global:isDarkMode) { "Dark Mode" } else { "Light Mode" }
            Write-LogConsole "Switched interface to $currentMode" "THEME"
        })
    }

    # Initialize theme (Light Mode default)
    Apply-AppTheme -IsDark $false


    # Helper: Real-time Terminal Logging
    function Write-LogConsole {
        param(
            [Parameter(Mandatory=$true)][string]$Message,
            [string]$Level = "INFO"
        )
        $timestamp = (Get-Date).ToString("HH:mm:ss")
        $formatted = "[$timestamp] [$Level] $Message"
        if ($sync.Form -and $sync.textboxConsole) {
            $sync.Form.Dispatcher.Invoke([action]{
                $sync.textboxConsole.AppendText("$formatted`r`n")
                if ($sync.scrollConsole) {
                    $sync.scrollConsole.ScrollToEnd()
                } else {
                    $sync.textboxConsole.ScrollToEnd()
                }
            })
        }
    }

    # Helper: Download URL Launcher
    function Invoke-DownloadUrl {
