    $radioButtonVolume.Add_Checked({ UpdateSelectionMode })
    $radioButtonRetail.Add_Checked({ UpdateSelectionMode })
    $radioButtonInstall.Add_Checked({ UpdateSelectionMode })
    $radioButtonDownload.Add_Checked({ UpdateSelectionMode })
