    UpdateSelectionMode

    # Background Async Operations
    $runspace = [runspacefactory]::CreateRunspace()
    $runspace.Open()
    $runspace.SessionStateProxy.SetVariable("sync", $sync)

    function Start-BackgroundOperation {
        param(
            [Parameter(Mandatory)][scriptblock]$Operation
        )

        if ($sync.isBusy) {
            return
        }

        if ($sync.lastPowerShell) {
            try { $sync.lastPowerShell.Dispose() } catch {}
            $sync.lastPowerShell = $null
        }

        $sync.isBusy = $true
        UpdateSelectionMode

        $powerShellInstance = [powershell]::Create().AddScript($Operation)
        $powerShellInstance.Runspace = $runspace
        $sync.lastPowerShell = $powerShellInstance
        $null = $powerShellInstance.BeginInvoke()
    }

    $sync.RestoreUiAction = [action]{
        $sync.buttonSubmit.IsHitTestVisible = $true
        $sync.buttonSubmit.Opacity = 1
        $sync.buttonClearSelection.IsHitTestVisible = $true
        $sync.buttonClearSelection.Opacity = 1
        if ($sync.panelDeployProgress) { $sync.panelDeployProgress.Visibility = "Collapsed" }
        if ($sync.badgeDeployConfig) { $sync.badgeDeployConfig.Visibility = "Visible" }
        $sync.isBusy = $false

        # Keep buttonSubmit hidden if user is on Tab 3 or Tab 4
        if ($sync.tabNavInstall -and -not $sync.tabNavInstall.IsChecked) {
            $sync.buttonSubmit.Visibility = "Collapsed"
            $sync.buttonClearSelection.Visibility = "Collapsed"
        }
    }

    $sync.ShowErrorAction = [action]{
        $sync.progressbar.Visibility = "Collapsed"
        $sync.textbox.Visibility = "Visible"
        $sync.textbox.Foreground = "#FFF43F5E"
        $sync.textbox.Text = $sync.errorMessage
        if ($sync.tabNavInstall -and $sync.tabNavInstall.IsChecked) {
            $sync.buttonSubmit.Visibility = "Visible"
            $sync.buttonSubmit.Content = "Start Deployment"
        }
        & $sync.RestoreUiAction
    }

# Preparation for download and install
    function PreparingOffice {
        if ($radioButtonDownload.IsChecked) {
            $workingDir = New-Item -Path $env:userprofile\Desktop\$productId -ItemType Directory -Force
            Set-Location $workingDir
            Invoke-Item $workingDir
        }

        if ($radioButtonInstall.IsChecked) {
            $workingDir = New-Item -Path $env:temp\ClickToRun\$productId -ItemType Directory -Force
            Set-Location $workingDir
        }

        New-Item $workingDir\Configuration -ItemType Directory -Force
        $configurationFile = "configuration-x$arch.xml"
        New-Item .\Configuration\$configurationFile -ItemType File -Force
        Add-Content .\Configuration\$configurationFile -Value "<Configuration>"
        Add-content .\Configuration\$configurationFile -Value "<Add OfficeClientEdition=`"$arch`">"
        Add-content .\Configuration\$configurationFile -Value "<Product ID=`"$productId`">"
        Add-content .\Configuration\$configurationFile -Value "<Language ID=`"$languageId`"/>"
        Add-Content .\Configuration\$configurationFile -Value "</Product>"
        Add-Content .\Configuration\$configurationFile -Value "</Add>"
        Add-Content .\Configuration\$configurationFile -Value "</Configuration>"

        $batchFile = "Install-$($arch)bit.bat"
        New-Item $batchFile -ItemType File -Force
        Add-content $batchFile -Value "%~dp0Configuration\ClickToRun.exe /configure %~dp0Configuration\$configurationFile"

        # Detect if user selected Office 2013
        $isOffice2013 = ($radioButton2013Pro.IsChecked -or $radioButton2013Std.IsChecked -or $radioButton2013ProjectPro.IsChecked -or
                         $radioButton2013ProjectStd.IsChecked -or $radioButton2013VisioPro.IsChecked -or $radioButton2013VisioStd.IsChecked -or
                         $radioButton2013Word.IsChecked -or $radioButton2013Excel.IsChecked -or $radioButton2013PowerPoint.IsChecked -or
                         $radioButton2013Outlook.IsChecked -or $radioButton2013Publisher.IsChecked -or $radioButton2013Access.IsChecked)

        if ($isOffice2013) {
            # Official Microsoft Office 2013 Deployment Tool (ODT 2013 - ID: 36778)
            try {
                $odtPage = Invoke-WebRequest -Uri "https://www.microsoft.com/en-us/download/details.aspx?id=36778" -UseBasicParsing -TimeoutSec 15
                if ($odtPage.Content -match 'https://download\.microsoft\.com/download/[^\s"<>]+/officedeploymenttool[^\s"<>]*\.exe') {
                    $odtUrl = $Matches[0]
                } else {
                    $odtUrl = "https://download.microsoft.com/download/6/2/3/6230f7a2-d8a9-478b-ac5c-57091b632fcf/officedeploymenttool_x86_5031-1000.exe"
                }
            } catch {
                $odtUrl = "https://download.microsoft.com/download/6/2/3/6230f7a2-d8a9-478b-ac5c-57091b632fcf/officedeploymenttool_x86_5031-1000.exe"
            }
        } else {
            # Modern ODT for Office 2016/2019/2021/2024/M365 (ID: 49117)
            try {
                $odtPage = Invoke-WebRequest -Uri "https://www.microsoft.com/en-us/download/details.aspx?id=49117" -UseBasicParsing -TimeoutSec 15
                if ($odtPage.Content -match 'https://download\.microsoft\.com/download/[^\s"<>]+/officedeploymenttool[^\s"<>]*\.exe') {
                    $odtUrl = $Matches[0]
                } else {
                    $odtUrl = "https://download.microsoft.com/download/6c1eeb25-cf8b-41d9-8d0d-cc1dbc032140/officedeploymenttool_20326-20112.exe"
                }
            } catch {
                $odtUrl = "https://download.microsoft.com/download/6c1eeb25-cf8b-41d9-8d0d-cc1dbc032140/officedeploymenttool_20326-20112.exe"
            }
        }

        # Download self-extracting ODT installer
        $odtFile = "$workingDir\Configuration\odt.exe"
        (New-Object Net.WebClient).DownloadFile($odtUrl, $odtFile)

        # Extract setup.exe (ClickToRun.exe) quietly from the ODT installer
        Start-Process -FilePath $odtFile -ArgumentList "/quiet /extract:`"$workingDir\Configuration`"" -Wait -NoNewWindow
        
        # Ensure ClickToRun.exe is replaced cleanly without throwing IO error
        if (Test-Path "$workingDir\Configuration\setup.exe") {
            if (Test-Path "$workingDir\Configuration\ClickToRun.exe") {
                Remove-Item -Path "$workingDir\Configuration\ClickToRun.exe" -Force -ErrorAction SilentlyContinue
            }
            Move-Item -Path "$workingDir\Configuration\setup.exe" -Destination "$workingDir\Configuration\ClickToRun.exe" -Force -ErrorAction SilentlyContinue
        }
        if (Test-Path $odtFile) {
            Remove-Item $odtFile -Force -ErrorAction SilentlyContinue
        }

        $sync.configurationFile = $configurationFile
        $sync.workingDir = $workingDir
    }
    
# Creating script block for download and install
    $DownloadInstallOffice = {
        trap {
            $sync.isBusy = $false
            $sync.errorMessage = $_.Exception.Message
            $sync.Form.Dispatcher.Invoke($sync.ShowErrorAction)
            continue
        }

        $sync.Form.Dispatcher.Invoke([action] {
            $sync.buttonSubmit.Visibility = "Collapsed"
            if ($sync.badgeDeployConfig) { $sync.badgeDeployConfig.Visibility = "Collapsed" }
            if ($sync.panelDeployProgress) { $sync.panelDeployProgress.Visibility = "Visible" }
            $sync.progressbar.Visibility = "Visible"
            $sync.textbox.Visibility = "Visible"
            $sync.textbox.Text = "$($sync.UIstatus) $($sync.productName) $($sync.arch)-bit ($($sync.language))..."
            $sync.ProgressBar.BorderBrush = "#FF6366F1"
            $sync.ProgressBar.IsIndeterminate = $true
        })

        $timestamp = (Get-Date).ToString("HH:mm:ss")
        $sync.Form.Dispatcher.Invoke([action]{
            $sync.textboxConsole.AppendText("[$timestamp] [INFO] Target Product: $($sync.productName) ($($sync.productId))`r`n")
            $sync.textboxConsole.AppendText("[$timestamp] [INFO] Mode: $($sync.mode) | Architecture: $($sync.arch)-bit | Language: $($sync.language)`r`n")
            $sync.textboxConsole.AppendText("[$timestamp] [INFO] Working Directory: $($sync.workingDir)`r`n")
            $sync.textboxConsole.AppendText("[$timestamp] [RUNNING] Launching Microsoft ClickToRun engine...`r`n")
            $sync.textboxConsole.ScrollToEnd()
        })

        Set-Location -Path $($sync.workingDir)
        Start-Process -FilePath .\Configuration\ClickToRun.exe -ArgumentList "$($sync.mode) .\Configuration\$($sync.configurationFile)" -NoNewWindow -Wait
                
        $timestampDone = (Get-Date).ToString("HH:mm:ss")
        $sync.Form.Dispatcher.Invoke([action] {
            $sync.buttonSubmit.Visibility = 'Visible'
            $sync.buttonSubmit.Content = 'Start Deployment'
            if ($sync.panelDeployProgress) { $sync.panelDeployProgress.Visibility = "Collapsed" }
            if ($sync.badgeDeployConfig) { $sync.badgeDeployConfig.Visibility = "Visible" }
            $sync.textbox.Visibility = 'Collapsed'
            $sync.ProgressBar.Visibility = 'Collapsed'
            $sync.ProgressBar.Value = '0'
            $sync.textboxConsole.AppendText("[$timestampDone] [SUCCESS] Operation $($sync.mode) for $($sync.productName) completed successfully.`r`n")
            $sync.textboxConsole.ScrollToEnd()
        })
        $sync.isBusy = $false
        $sync.Form.Dispatcher.Invoke($sync.RestoreUiAction)
    }

