# TAB 3 ACTIONS: Check OSPP License Status
    $FindOsppVbs = {
        $osppPaths = @(
            "C:\Program Files\Microsoft Office\root\Office16\ospp.vbs",
            "C:\Program Files (x86)\Microsoft Office\root\Office16\ospp.vbs",
            "C:\Program Files\Microsoft Office\Office16\ospp.vbs",
            "C:\Program Files (x86)\Microsoft Office\Office16\ospp.vbs",
            "C:\Program Files\Microsoft Office\Office15\ospp.vbs",
            "C:\Program Files (x86)\Microsoft Office\Office15\ospp.vbs",
            "C:\Program Files\Microsoft Office\Office14\ospp.vbs",
            "C:\Program Files (x86)\Microsoft Office\Office14\ospp.vbs"
        )
        foreach ($p in $osppPaths) {
            if (Test-Path $p) { return $p }
        }
        $regC2R = (Get-ItemProperty "HKLM:\SOFTWARE\Microsoft\Office\ClickToRun\Configuration" -ErrorAction SilentlyContinue).InstallationPath
        if ($regC2R) {
            $dyn = Join-Path $regC2R "root\Office16\ospp.vbs"
            if (Test-Path $dyn) { return $dyn }
        }
        return $null
    }

    $buttonCheckOSPP.Add_Click({
        Write-LogConsole "Scanning for Office Software Protection Platform (ospp.vbs)..." "CHECK"
        $found = & $FindOsppVbs

        if (-not $found) {
            Write-LogConsole "ospp.vbs not found. Is Microsoft Office installed on this machine?" "ERROR"
            return
        }

        $sync.osppPath = $found
        Write-LogConsole "Found: $found. Querying license status..." "INFO"
        Start-BackgroundOperation -Operation {
            $vbsPath = $sync.osppPath
            $osppCmd = cscript.exe //Nologo "$vbsPath" /dstatus
            foreach ($line in $osppCmd) {
                if ($line.Trim()) {
                    $sync.Form.Dispatcher.Invoke([action]{
                        $sync.textboxConsole.AppendText("[OSPP] $line`r`n")
                        $sync.textboxConsole.ScrollToEnd()
                    })
                }
            }
            $sync.Form.Dispatcher.Invoke($sync.RestoreUiAction)
        }
    })


    # Convert Retail to Volume (GVLK)
    $buttonConvertVolume.Add_Click({
        if ($sync.isBusy) { return }
        Write-LogConsole "Initiating Retail to Volume license conversion..." "CONVERT"
        $found = & $FindOsppVbs

        if (-not $found) {
            Write-LogConsole "ospp.vbs not found. Is Microsoft Office installed on this machine?" "ERROR"
            return
        }

        $sync.osppPath = $found
        Start-BackgroundOperation -Operation {
            $vbs = $sync.osppPath
            $sync.Form.Dispatcher.Invoke([action]{
                $sync.textboxConsole.AppendText("[CONVERT] Scanning installed Office configuration...`r`n")
                $sync.textboxConsole.ScrollToEnd()
            })

            # Detect Office Version from ClickToRun registry or OSPP status
            $c2rConfig = Get-ItemProperty "HKLM:\SOFTWARE\Microsoft\Office\ClickToRun\Configuration" -ErrorAction SilentlyContinue
            $productIds = if ($c2rConfig.ProductReleaseIds) { $c2rConfig.ProductReleaseIds } else { "" }
            $versionReport = if ($c2rConfig.VersionToReport) { $c2rConfig.VersionToReport } else { "" }

            # GVLK Keys map (Official Microsoft KMS Client Setup Keys)
            $gvlkMap = @{
                "Office2024" = @{ Key = "2T8H8-ND4W7-6GW28-7FCX2-XWTY7"; Name = "Office 2024 LTSC Pro Plus" }
                "Office2021" = @{ Key = "FXYTK-NJDJG-GBMWK-W887X-3GQHR"; Name = "Office 2021 LTSC Pro Plus" }
                "Office2019" = @{ Key = "NMMKJ-6RK4F-KMJVX-8D9MJ-6MWKP"; Name = "Office 2019 Pro Plus" }
                "Office2016" = @{ Key = "XQNVK-8JYDB-WJ9W3-YJ8YR-WFG99"; Name = "Office 2016 Pro Plus" }
            }

            # Select target GVLK based on installed Office products
            $target = $null
            if ($productIds -match '2024') {
                $target = $gvlkMap["Office2024"]
            } elseif ($productIds -match '2021') {
                $target = $gvlkMap["Office2021"]
            } elseif ($productIds -match '2019') {
                $target = $gvlkMap["Office2019"]
            } elseif ($productIds -match '2016' -or $productIds -match 'O365' -or $productIds -match 'ProPlus') {
                $target = $gvlkMap["Office2021"]
            } else {
                # Fallback based on typical modern deployment
                $target = $gvlkMap["Office2024"]
            }

            $sync.Form.Dispatcher.Invoke([action]{
                $sync.textboxConsole.AppendText("[CONVERT] Target Volume Suite: $($target.Name)`r`n")
                $sync.textboxConsole.AppendText("[CONVERT] Installing GVLK Key: $($target.Key)...`r`n")
                $sync.textboxConsole.ScrollToEnd()
            })

            $inpkeyOutput = cscript.exe //Nologo "$vbs" "/inpkey:$($target.Key)"
            foreach ($line in $inpkeyOutput) {
                if ($line.Trim()) {
                    $sync.Form.Dispatcher.Invoke([action]{
                        $sync.textboxConsole.AppendText("[OSPP] $line`r`n")
                        $sync.textboxConsole.ScrollToEnd()
                    })
                }
            }

            $sync.Form.Dispatcher.Invoke([action]{
                $sync.textboxConsole.AppendText("[SUCCESS] License conversion completed! You can now activate via KMS or Inspect Status.`r`n")
                $sync.textboxConsole.ScrollToEnd()
            })
            $sync.Form.Dispatcher.Invoke($sync.RestoreUiAction)
        }
    })

    # Rearm Grace Period
    $buttonRearmOSPP.Add_Click({
        Write-LogConsole "Attempting to rearm Office grace period..." "REARM"
        $found = & $FindOsppVbs

        if ($found) {
            $sync.osppPath = $found
            Start-BackgroundOperation -Operation {
                $vbsPath = $sync.osppPath
                $rearmCmd = cscript.exe //Nologo "$vbsPath" /rearm
                foreach ($line in $rearmCmd) {
                    if ($line.Trim()) {
                        $sync.Form.Dispatcher.Invoke([action]{
                            $sync.textboxConsole.AppendText("[REARM] $line`r`n")
                            $sync.textboxConsole.ScrollToEnd()
                        })
                    }
                }
                $sync.Form.Dispatcher.Invoke($sync.RestoreUiAction)
            }
        } else {
            Write-LogConsole "Office installation not found to rearm." "WARN"
        }
    })

    # Clean Office Cache & Fix Crash
    $buttonCleanCache.Add_Click({
        if ($sync.isBusy) { return }
        Write-LogConsole "Cleaning Office document caches and fixing crash issues..." "CLEAN"
        Start-BackgroundOperation -Operation {
            $sync.Form.Dispatcher.Invoke([action]{
                $sync.textboxConsole.AppendText("[CLEAN] Terminating running Office processes (Word, Excel, PowerPoint, Outlook, Access)...`r`n")
                $sync.textboxConsole.ScrollToEnd()
            })

            $procs = @("WINWORD", "EXCEL", "POWERPNT", "OUTLOOK", "MSACCESS", "ONENOTE", "MSPUB")
            foreach ($p in $procs) {
                Get-Process -Name $p -ErrorAction SilentlyContinue | Stop-Process -Force -ErrorAction SilentlyContinue
            }

            $cacheDirs = @(
                "$env:LOCALAPPDATA\Microsoft\Office\16.0\OfficeFileCache",
                "$env:LOCALAPPDATA\Microsoft\Office\15.0\OfficeFileCache",
                "$env:LOCALAPPDATA\Microsoft\Office\Spw"
            )

            $deletedCount = 0
            foreach ($dir in $cacheDirs) {
                if (Test-Path $dir) {
                    $sync.Form.Dispatcher.Invoke([action]{
                        $sync.textboxConsole.AppendText("[CLEAN] Removing cache folder: $dir...`r`n")
                        $sync.textboxConsole.ScrollToEnd()
                    })
                    try {
                        Remove-Item -Path $dir -Recurse -Force -ErrorAction Stop
                        $deletedCount++
                    } catch {
                        $err = $_.Exception.Message
                        $sync.Form.Dispatcher.Invoke([action]{
                            $sync.textboxConsole.AppendText("[WARN] Could not remove $($dir): $err`r`n")
                            $sync.textboxConsole.ScrollToEnd()
                        })
                    }
                }
            }

            # Backup and reset corrupt Word Normal template if present
            $normalTemplate = "$env:APPDATA\Microsoft\Templates\Normal.dotm"
            if (Test-Path $normalTemplate) {
                $bak = "$env:APPDATA\Microsoft\Templates\Normal.dotm.bak_$(Get-Date -Format 'yyyyMMddHHmmss')"
                Rename-Item -Path $normalTemplate -NewName $bak -Force -ErrorAction SilentlyContinue
                $sync.Form.Dispatcher.Invoke([action]{
                    $sync.textboxConsole.AppendText("[CLEAN] Corrupt Word template Normal.dotm backed up and reset.`r`n")
                    $sync.textboxConsole.ScrollToEnd()
                })
            }

            $sync.Form.Dispatcher.Invoke([action]{
                $sync.textboxConsole.AppendText("[SUCCESS] Office cache cleanup complete ($deletedCount directories purged). Crash causes resolved.`r`n")
                $sync.textboxConsole.ScrollToEnd()
            })
            $sync.Form.Dispatcher.Invoke($sync.RestoreUiAction)
        }
    })

    # Helper to get ClickToRun execution context
    $GetClickToRunInfo = {
        $c2rConfig = Get-ItemProperty "HKLM:\SOFTWARE\Microsoft\Office\ClickToRun\Configuration" -ErrorAction SilentlyContinue
        $platform = if ($c2rConfig.Platform) { $c2rConfig.Platform } else { "x64" }
        $culture = if ($c2rConfig.ClientCulture) { $c2rConfig.ClientCulture } else { "en-us" }
        $productReleaseIds = if ($c2rConfig.ProductReleaseIds) { $c2rConfig.ProductReleaseIds } else { "O365HomePremRetail" }

        $paths = @(
            $c2rConfig.ClientFolder,
            "C:\Program Files\Common Files\microsoft shared\ClickToRun",
            "C:\Program Files (x86)\Common Files\microsoft shared\ClickToRun"
        )
        $exePath = $null
        foreach ($p in $paths) {
            if ($p) {
                $candidate = Join-Path $p "OfficeClickToRun.exe"
                if (Test-Path $candidate) { $exePath = $candidate; break }
            }
        }
        return @{ Exe = $exePath; Platform = $platform; Culture = $culture; ProductReleaseIds = $productReleaseIds }
    }

    # Quick Repair
    $buttonQuickRepair.Add_Click({
        Write-LogConsole "Starting Office Quick Repair..." "REPAIR"
        $c2r = & $GetClickToRunInfo
        if ($c2r.Exe) {
            Start-Process -FilePath $c2r.Exe -ArgumentList "scenario=Repair platform=$($c2r.Platform) culture=$($c2r.Culture) RepairType=QuickRepair"
            Write-LogConsole "Quick Repair dialog launched." "SUCCESS"
        } else {
            Write-LogConsole "ClickToRun service not detected on system." "ERROR"
        }
    })

    # Online Repair
    $buttonOnlineRepair.Add_Click({
        Write-LogConsole "Starting Office Full Online Repair..." "REPAIR"
        $c2r = & $GetClickToRunInfo
        if ($c2r.Exe) {
            Start-Process -FilePath $c2r.Exe -ArgumentList "scenario=Repair platform=$($c2r.Platform) culture=$($c2r.Culture) RepairType=FullRepair"
            Write-LogConsole "Online Repair dialog launched." "SUCCESS"
        } else {
            Write-LogConsole "ClickToRun service not detected on system." "ERROR"
        }
    })

# TAB 4 ACTIONS: Uninstall Office
    $UninstallOffice = {
        trap {
            $sync.isBusy = $false
            $sync.errorMessage = $_.Exception.Message
            $sync.Form.Dispatcher.Invoke($sync.ShowErrorAction)
            continue
        }

        $timestamp = (Get-Date).ToString("HH:mm:ss")
        $sync.Form.Dispatcher.Invoke([action] {
            $sync.progressbar.Visibility = "Visible"
            $sync.textbox.Visibility = "Visible"
            $sync.textbox.Text = "Uninstalling Microsoft Office..."
            $sync.ProgressBar.BorderBrush = "#FFF43F5E"
            $sync.ProgressBar.IsIndeterminate = $true
            $sync.textboxConsole.AppendText("[$timestamp] [UNINSTALL] Preparing removal configuration...`r`n")
            $sync.textboxConsole.ScrollToEnd()
        })
        
        Set-Location -Path $($sync.workingDir)
        Set-Content -Path "$($sync.workingDir)\configuration.xml" -Value @"
<Configuration>
  <Remove All="TRUE" />
  <Display Level="None" AcceptEULA="TRUE" />
</Configuration>
"@

        # Dynamically fetch the official Microsoft Office Deployment Tool (ODT) download page
        try {
            $odtPage = Invoke-WebRequest -Uri "https://www.microsoft.com/en-us/download/details.aspx?id=49117" -UseBasicParsing -TimeoutSec 15
            if ($odtPage.Content -match 'https://download\.microsoft\.com/download/[^\s"<>]+/officedeploymenttool[^\s"<>]*\.exe') {
                $odtUrl = $Matches[0]
            } else {
                $odtUrl = "https://download.microsoft.com/download/6/c/1/6c1eeb25-cf8b-41d9-8d0d-cc1dbc032140/officedeploymenttool_20228-20124.exe"
            }
        } catch {
            $odtUrl = "https://download.microsoft.com/download/6/c/1/6c1eeb25-cf8b-41d9-8d0d-cc1dbc032140/officedeploymenttool_20228-20124.exe"
        }

        # Download self-extracting ODT installer
        $odtFile = "$($sync.workingDir)\odt.exe"
        (New-Object Net.WebClient).DownloadFile($odtUrl, $odtFile)

        # Extract setup.exe (ClickToRun.exe) quietly from the ODT installer
        Start-Process -FilePath $odtFile -ArgumentList "/quiet /extract:`"$($sync.workingDir)`"" -Wait -NoNewWindow
        
        # Ensure ClickToRun.exe is replaced cleanly without throwing IO error
        if (Test-Path "$($sync.workingDir)\setup.exe") {
            if (Test-Path "$($sync.workingDir)\ClickToRun.exe") {
                Remove-Item -Path "$($sync.workingDir)\ClickToRun.exe" -Force -ErrorAction SilentlyContinue
            }
            Move-Item -Path "$($sync.workingDir)\setup.exe" -Destination "$($sync.workingDir)\ClickToRun.exe" -Force -ErrorAction SilentlyContinue
        }
        if (Test-Path $odtFile) {
            Remove-Item $odtFile -Force -ErrorAction SilentlyContinue
        }

        $timestampRun = (Get-Date).ToString("HH:mm:ss")
        $sync.Form.Dispatcher.Invoke([action] {
            $sync.textboxConsole.AppendText("[$timestampRun] [RUNNING] Executing ClickToRun removal configuration...`r`n")
            $sync.textboxConsole.ScrollToEnd()
        })

        Start-Process -FilePath .\ClickToRun.exe -ArgumentList "/configure .\configuration.xml" -NoNewWindow -Wait

        $timestampEnd = (Get-Date).ToString("HH:mm:ss")
        $sync.Form.Dispatcher.Invoke([action] {
            $sync.buttonSubmit.Visibility = 'Visible'
            $sync.buttonSubmit.Content = 'Start Deployment'
            $sync.textbox.Visibility = 'Collapsed'
            $sync.ProgressBar.Visibility = 'Collapsed'
            $sync.ProgressBar.Value = '0'
            $sync.textboxConsole.AppendText("[$timestampEnd] [SUCCESS] All Office products have been uninstalled.`r`n")
            $sync.textboxConsole.ScrollToEnd()
        })
        $sync.isBusy = $false
        $sync.Form.Dispatcher.Invoke($sync.RestoreUiAction)

        # Cleanup
        Set-Location ..
        Remove-Item ClickToRunU -Recurse -Force -ErrorAction SilentlyContinue
    }

# TAB 4 ACTIONS: Advanced Uninstall & Clean Suite

    # 1. Fast ClickToRun Uninstall
    $buttonQuickUninstall.Add_Click({
        if ($sync.isBusy) { return }
        Write-LogConsole "Starting Fast ClickToRun uninstallation..." "UNINSTALL"
        $c2r = & $GetClickToRunInfo
        if ($c2r.Exe) {
            Start-BackgroundOperation -Operation {
                $c2r = & $GetClickToRunInfo
                $timestamp = (Get-Date).ToString("HH:mm:ss")
                $sync.Form.Dispatcher.Invoke([action]{
                    $sync.textboxConsole.AppendText("[$timestamp] [RUNNING] Launching Office ClickToRun removal process...`r`n")
                    $sync.textboxConsole.ScrollToEnd()
                })

                # Construct products to remove argument
                $prodToRemove = "$($c2r.ProductReleaseIds).16_$($c2r.Culture)_x-none"
                $c2rArgs = "scenario=install scenariosubtype=uninstall productstoremove=$prodToRemove culture=$($c2r.Culture) DisplayLevel=True ForceAppShutdown=True"
                
                # If DisplayLevel=True doesn't trigger or user wants silent, we also accept ARP uninstallation
                $regUninstall = Get-ItemProperty 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\*' -ErrorAction SilentlyContinue |
                    Where-Object { $_.UninstallString -match 'OfficeClickToRun\.exe.*scenario=install' } |
                    Select-Object -First 1

                if ($regUninstall.UninstallString) {
                    $uStr = $regUninstall.UninstallString
                    if ($uStr -match '"([^"]+)"\s*(.*)') {
                        $exe = $Matches[1]
                        $args = $Matches[2] + " DisplayLevel=True ForceAppShutdown=True"
                        Start-Process -FilePath $exe -ArgumentList $args -Wait
                    } else {
                        Start-Process -FilePath $c2r.Exe -ArgumentList $c2rArgs -Wait
                    }
                } else {
                    Start-Process -FilePath $c2r.Exe -ArgumentList $c2rArgs -Wait
                }

                $timestampEnd = (Get-Date).ToString("HH:mm:ss")
                $sync.Form.Dispatcher.Invoke([action]{
                    $sync.textboxConsole.AppendText("[$timestampEnd] [SUCCESS] Fast ClickToRun removal process completed.`r`n")
                    $sync.textboxConsole.ScrollToEnd()
                })
                $sync.Form.Dispatcher.Invoke($sync.RestoreUiAction)
            }
        } else {
            Write-LogConsole "Local ClickToRun service not found. Please use 'Uninstall All' via ODT." "WARN"
        }
    })

    # 2. Standard ODT Clean Removal (All Apps)
    $buttonRemoveAll.Add_Click({
        if ($sync.isBusy) { return }
        Write-LogConsole "Initiating standard ODT uninstallation of all Office suites..." "UNINSTALL"
        $workingDir = New-Item -Path "$env:temp\ClickToRunU" -ItemType Directory -Force
        Set-Location $workingDir
        $sync.workingDir = $workingDir

        Start-BackgroundOperation -Operation $UninstallOffice
    })

    # 3. Deep Clean SaRA Scrubber (Official Microsoft)
    $buttonLaunchSaRA.Add_Click({
        if ($sync.isBusy) { return }
        Write-LogConsole "Downloading official Microsoft SaRA Enterprise Scrubber..." "SARA"
        Start-BackgroundOperation -Operation {
            $saraDir = "$env:temp\SaRAScrub"
            New-Item -Path $saraDir -ItemType Directory -Force | Out-Null
            if (-not (Test-Path "$saraDir\SaRA\GetHelpCmd.exe")) {
                (New-Object Net.WebClient).DownloadFile('https://aka.ms/SaRA_EnterpriseVersionFiles', "$saraDir\SaRA.zip")
                Expand-Archive -Path "$saraDir\SaRA.zip" -DestinationPath "$saraDir\SaRA" -Force
            }
            
            $saraExe = if (Test-Path "$saraDir\SaRA\GetHelpCmd.exe") { 
                "$saraDir\SaRA\GetHelpCmd.exe" 
            } elseif (Test-Path "$saraDir\SaRA\SaRACmd.exe") { 
                "$saraDir\SaRA\SaRACmd.exe" 
            } else { 
                $null 
            }

            if (-not $saraExe) {
                $timestamp = (Get-Date).ToString("HH:mm:ss")
                $sync.Form.Dispatcher.Invoke([action]{
                    $sync.textboxConsole.AppendText("[$timestamp] [ERROR] Không tìm thấy file thực thi SaRA/GetHelpCmd trong gói giải nén.`r`n")
                    $sync.textboxConsole.ScrollToEnd()
                })
                $sync.isBusy = $false
                $sync.Form.Dispatcher.Invoke($sync.RestoreUiAction)
                return
            }

            $timestamp = (Get-Date).ToString("HH:mm:ss")
            $sync.Form.Dispatcher.Invoke([action]{
                $sync.textboxConsole.AppendText("[$timestamp] [RUNNING] Khởi chạy SaRA OfficeScrubScenario (Dọn dẹp triệt để Office)...`r`n")
                $sync.textboxConsole.ScrollToEnd()
            })

            # Stream real-time console output from GetHelpCmd/SaRA
            $pinfo = New-Object System.Diagnostics.ProcessStartInfo
            $pinfo.FileName = $saraExe
            $pinfo.Arguments = "-S OfficeScrubScenario -AcceptEula"
            $pinfo.RedirectStandardOutput = $true
            $pinfo.RedirectStandardError = $true
            $pinfo.UseShellExecute = $false
            $pinfo.CreateNoWindow = $true

            $process = New-Object System.Diagnostics.Process
            $process.StartInfo = $pinfo
            $process.Start() | Out-Null

            while (-not $process.HasExited) {
                $line = $process.StandardOutput.ReadLine()
                if ($line -and $line.Trim()) {
                    $sync.Form.Dispatcher.Invoke([action]{
                        $sync.textboxConsole.AppendText("[SARA] $line`r`n")
                        $sync.textboxConsole.ScrollToEnd()
                    })
                }
            }
            # Flush remaining output
            $remaining = $process.StandardOutput.ReadToEnd()
            if ($remaining) {
                foreach ($remLine in $remaining.Split("`n")) {
                    if ($remLine.Trim()) {
                        $sync.Form.Dispatcher.Invoke([action]{
                            $sync.textboxConsole.AppendText("[SARA] $($remLine.Trim())`r`n")
                            $sync.textboxConsole.ScrollToEnd()
                        })
                    }
                }
            }

            $timestampEnd = (Get-Date).ToString("HH:mm:ss")
            $sync.Form.Dispatcher.Invoke([action]{
                $sync.textboxConsole.AppendText("[$timestampEnd] [SUCCESS] Hoàn tất quá trình dọn dẹp SaRA Deep Scrub.`r`n")
                $sync.textboxConsole.ScrollToEnd()
            })
            $sync.isBusy = $false
            $sync.Form.Dispatcher.Invoke($sync.RestoreUiAction)
        }
    })

    # 4. Remove Microsoft Store / OEM Office Apps (AppX)
    $buttonRemoveAppx.Add_Click({
        if ($sync.isBusy) { return }
        Write-LogConsole "Scanning and removing Microsoft Store Office packages (AppX)..." "STORE"
        Start-BackgroundOperation -Operation {
            $targets = @(
                "*Microsoft.Office.Desktop*",
                "*MicrosoftOfficeHub*",
                "*Microsoft.OfficePushNotificationUtility*"
            )
            $foundAny = $false
            foreach ($target in $targets) {
                $packages = Get-AppxPackage -Name $target -ErrorAction SilentlyContinue
                foreach ($pkg in $packages) {
                    $foundAny = $true
                    $pkgName = $pkg.Name
                    $sync.Form.Dispatcher.Invoke([action]{
                        $sync.textboxConsole.AppendText("[STORE] Removing AppX package: $pkgName...`r`n")
                        $sync.textboxConsole.ScrollToEnd()
                    })
                    Remove-AppxPackage -Package $pkg.PackageFullName -ErrorAction SilentlyContinue
                }
            }
            $statusMsg = if ($foundAny) { "[SUCCESS] Microsoft Store Office packages successfully removed." } else { "[INFO] No pre-installed Microsoft Store Office packages found." }
            $sync.Form.Dispatcher.Invoke([action]{
                $sync.textboxConsole.AppendText("$statusMsg`r`n")
                $sync.textboxConsole.ScrollToEnd()
            })
            $sync.Form.Dispatcher.Invoke($sync.RestoreUiAction)
        }
    })

    # 5. Clean Office Licenses & Reset Activation Tokens
    $buttonCleanLicenses.Add_Click({
        if ($sync.isBusy) { return }
        Write-LogConsole "Scanning for lingering Office product keys & license tokens..." "LICENSE"
        $found = & $FindOsppVbs
        if (-not $found) {
            Write-LogConsole "ospp.vbs not found. No installed Office licensing platform detected." "WARN"
            return
        }

        $sync.osppPath = $found
        Start-BackgroundOperation -Operation {
            $vbs = $sync.osppPath
            $sync.Form.Dispatcher.Invoke([action]{
                $sync.textboxConsole.AppendText("[LICENSE] Querying installed Office product keys...`r`n")
                $sync.textboxConsole.ScrollToEnd()
            })

            $dstatus = cscript.exe //Nologo "$vbs" /dstatus
            $keys = @()
            foreach ($line in $dstatus) {
                if ($line -match 'Last 5 characters of installed product key:\s*([A-Z0-9]{5})') {
                    $keys += $Matches[1]
                }
            }

            if ($keys.Count -gt 0) {
                foreach ($key in $keys) {
                    $sync.Form.Dispatcher.Invoke([action]{
                        $sync.textboxConsole.AppendText("[LICENSE] Uninstalling product key: $key...`r`n")
                        $sync.textboxConsole.ScrollToEnd()
                    })
                    $unpkeyResult = cscript.exe //Nologo "$vbs" /unpkey:$key
                }
                $sync.Form.Dispatcher.Invoke([action]{
                    $sync.textboxConsole.AppendText("[SUCCESS] All ($($keys.Count)) Office product keys removed successfully.`r`n")
                    $sync.textboxConsole.ScrollToEnd()
                })
            } else {
                $sync.Form.Dispatcher.Invoke([action]{
                    $sync.textboxConsole.AppendText("[INFO] No active product keys found to remove.`r`n")
                    $sync.textboxConsole.ScrollToEnd()
                })
            }
            $sync.Form.Dispatcher.Invoke($sync.RestoreUiAction)
        }
    })

    $Form.Add_Closing({
        if ($sync.lastPowerShell) {
            try { $sync.lastPowerShell.Dispose() } catch {}
            $sync.lastPowerShell = $null
        }
        if ($runspace) {
            try { $runspace.Close() } catch {}
            try { $runspace.Dispose() } catch {}
        }
    })

$null = $Form.ShowDialog()
